-- Recovered verbatim from the production Supabase migration ledger for L0 replay parity.
create or replace function public.hq_workforce_context_health(p_fact_id uuid,p_high_stakes boolean default true) returns table(status text,violation_code text) language plpgsql stable security invoker set search_path=public as $$ declare f public.hq_context_facts_cache%rowtype; rel numeric; src_active boolean; begin select * into f from public.hq_context_facts_cache where id=p_fact_id; if not found then return query select 'deny'::text,'FACT_NOT_FOUND'::text; return; end if; if f.value is null or f.confidence is null or f.confidence_source is null or btrim(f.confidence_source)='' then return query select 'deny'::text,'MALFORMED_CONTEXT'::text; return; end if; if f.freshness_expires_at<=now() then return query select 'deny'::text,'STALE_CONTEXT'::text; return; end if; select s.reliability_score,s.active into rel,src_active from public.hq_context_fact_definitions d join public.hq_context_sources s on s.id=d.source_id where d.id=f.fact_definition_id; if src_active is distinct from true then return query select 'deny'::text,'SOURCE_INACTIVE'::text; return; end if; if rel is null then return query select 'deny'::text,'SOURCE_RELIABILITY_UNKNOWN'::text; return; end if; if p_high_stakes and least(f.confidence,rel)<0.70 then return query select 'escalate'::text,'LOW_CONFIDENCE_HIGH_STAKES'::text; return; end if; return query select 'allow'::text,null::text; end $$;
revoke all on function public.hq_workforce_context_health(uuid,boolean) from public,anon,authenticated;
